"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Skeleton } from "@/components/ui/skeleton";
import {
  getBusArrivals,
  getNearbyBusStops,
  searchBusStops,
  type BusArrival,
  type GetBusArrivalsResult,
  type NearbyBusStop,
} from "@/lib/tfl/actions";
import {
  isValidLatLon,
  TRAFALGAR_SQUARE,
  truncateLatLon,
  type LatLonLabel,
} from "@/lib/tfl/geo";
import { Bus, Loader2, LocateFixed, MapPin, Search } from "lucide-react";
import { cn } from "@/lib/utils";

const LOCATION_CACHE_KEY = "tfl-bus-arrivals-location";

const readCachedLocation = (): LatLonLabel | null => {
  if (typeof window === "undefined") return null;
  try {
    const raw = window.localStorage.getItem(LOCATION_CACHE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as Partial<LatLonLabel>;
    if (
      typeof parsed.lat !== "number" ||
      typeof parsed.lon !== "number" ||
      typeof parsed.label !== "string" ||
      !isValidLatLon(parsed.lat, parsed.lon) ||
      parsed.label.trim().length === 0
    ) {
      return null;
    }
    const { lat, lon } = truncateLatLon(parsed.lat, parsed.lon);
    return { lat, lon, label: parsed.label.trim() };
  } catch {
    return null;
  }
};

const writeCachedLocation = (location: LatLonLabel): void => {
  if (typeof window === "undefined") return;
  try {
    const { lat, lon } = truncateLatLon(location.lat, location.lon);
    window.localStorage.setItem(
      LOCATION_CACHE_KEY,
      JSON.stringify({ lat, lon, label: location.label }),
    );
  } catch {
    // Quota / private mode — continue without persistence.
  }
};

/** Skeleton for the bus arrivals board — use in `loading.tsx` or Suspense. */
export const BusArrivalsSkeleton = () => (
  <div className="w-full space-y-4" aria-busy aria-label="Loading bus arrivals">
    <div className="space-y-2">
      <Skeleton className="h-7 w-56 max-w-full" />
      <Skeleton className="h-4 w-full max-w-md" />
    </div>
    <div className="flex flex-col gap-2 sm:flex-row">
      <Skeleton className="h-9 w-full sm:w-44" />
      <Skeleton className="h-9 flex-1" />
      <Skeleton className="h-9 w-full sm:w-24" />
    </div>
    <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
      {Array.from({ length: 4 }).map((_, i) => (
        <Skeleton key={i} className="h-20 w-full" />
      ))}
    </div>
    <div className="space-y-0 border-t border-border pt-4">
      {Array.from({ length: 6 }).map((_, i) => (
        <Skeleton key={i} className="my-2 h-10 w-full" />
      ))}
    </div>
  </div>
);

const formatTimeToStation = (seconds?: number): string => {
  if (seconds === undefined || seconds < 0) return "-";
  if (seconds < 60) return "Due";
  const mins = Math.floor(seconds / 60);
  return `${mins} min`;
};

const formatClockTime = (iso?: string): string | null => {
  if (!iso) return null;
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return null;
  return date.toLocaleTimeString("en-GB", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });
};

const formatDistance = (meters?: number): string => {
  if (meters === undefined) return "";
  if (meters < 1000) return `${Math.round(meters)}m`;
  return `${(meters / 1000).toFixed(1)}km`;
};

const formatDirection = (direction?: string): string | null => {
  if (!direction) return null;
  return direction.charAt(0).toUpperCase() + direction.slice(1).toLowerCase();
};

/** Compact TfL-style stop letter; sits inline after the stop name. */
const StopLetterBadge = ({ letter }: { letter?: string }) => {
  if (!letter) return null;
  return (
    <span
      className="inline-flex size-4 shrink-0 items-center justify-center rounded-full bg-red-600 text-[10px] font-bold leading-none text-white tabular-nums align-middle"
      aria-hidden
    >
      {letter}
    </span>
  );
};

/** Shared line chip for stop picker + arrivals list. */
const LineBadge = ({ line }: { line: string }) => (
  <span className="inline-flex h-5 min-w-5 items-center justify-center rounded-md bg-foreground px-1.5 text-[11px] font-bold leading-none tabular-nums text-background">
    {line}
  </span>
);

/** Numeric codes; avoid relying on the GeolocationPositionError global. */
const GEO_PERMISSION_DENIED = 1;
const GEO_POSITION_UNAVAILABLE = 2;
const GEO_TIMEOUT = 3;

const geolocationErrorMessage = (code: number): string => {
  switch (code) {
    case GEO_PERMISSION_DENIED:
      return "Location is blocked for this site. Use the lock icon in the address bar → Site settings → Location → Allow, then try again.";
    case GEO_POSITION_UNAVAILABLE:
      return "Location unavailable. Try again or search by stop name.";
    case GEO_TIMEOUT:
      return "Location request timed out. Try again.";
    default:
      return "Could not read your location.";
  }
};

export const BusArrivals = () => {
  const [stops, setStops] = useState<NearbyBusStop[]>([]);
  const [selectedStop, setSelectedStop] = useState<NearbyBusStop | null>(null);
  const [locationLabel, setLocationLabel] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [arrivalsResult, setArrivalsResult] = useState<GetBusArrivalsResult | null>(null);
  const [stopsError, setStopsError] = useState<string | null>(null);
  const [loadingLocation, setLoadingLocation] = useState(true);
  const [loadingSearch, setLoadingSearch] = useState(false);
  const [loadingArrivals, setLoadingArrivals] = useState(false);
  const hasBootstrapped = useRef(false);

  const loadArrivals = useCallback(async (stop: NearbyBusStop) => {
    setSelectedStop(stop);
    setLoadingArrivals(true);
    setArrivalsResult(null);
    try {
      const data = await getBusArrivals(stop.id, stop.name);
      setArrivalsResult(data);
    } catch {
      setArrivalsResult({
        ok: false,
        error: "Failed to load arrivals. Try another stop.",
      });
    } finally {
      setLoadingArrivals(false);
    }
  }, []);

  const handleNearbyFromCoords = useCallback(
    async (lat: number, lon: number, label: string) => {
      setStopsError(null);
      setStops([]);
      setSelectedStop(null);
      setArrivalsResult(null);
      setLocationLabel(label);

      try {
        const data = await getNearbyBusStops(lat, lon);
        if (data.ok === false) {
          setStopsError(data.error);
          return;
        }

        setStops(data.stops);
        await loadArrivals(data.stops[0]!);
      } catch {
        setStopsError("Failed to find nearby stops. Try searching by name.");
      }
    },
    [loadArrivals],
  );

  useEffect(() => {
    if (hasBootstrapped.current) return;
    hasBootstrapped.current = true;

    const cached = readCachedLocation();
    const location: LatLonLabel = cached ?? {
      lat: TRAFALGAR_SQUARE.lat,
      lon: TRAFALGAR_SQUARE.lon,
      label: TRAFALGAR_SQUARE.label,
    };
    if (!cached) {
      writeCachedLocation(location);
    }

    setLoadingLocation(true);
    void handleNearbyFromCoords(location.lat, location.lon, location.label).finally(() => {
      setLoadingLocation(false);
    });
  }, [handleNearbyFromCoords]);

  const handleUseLocation = async () => {
    if (loadingLocation || loadingSearch) return;

    if (typeof window !== "undefined" && !window.isSecureContext) {
      setStopsError(
        "Location needs a secure origin. Open via http://localhost:3001 (not a LAN IP like 192.168.x.x).",
      );
      return;
    }

    if (!navigator.geolocation) {
      setStopsError("Geolocation is not supported in this browser.");
      return;
    }

    // If already blocked, Chrome will not show the permission prompt again.
    try {
      const permission = await navigator.permissions?.query({
        name: "geolocation",
      });
      if (permission?.state === "denied") {
        setStopsError(
          "Location is blocked for this site. Use the lock icon in the address bar → Site settings → Location → Allow, then try again.",
        );
        return;
      }
    } catch {
      // permissions.query is optional; continue to getCurrentPosition.
    }

    setLoadingLocation(true);
    setStopsError(null);

    navigator.geolocation.getCurrentPosition(
      (position) => {
        const { lat, lon } = truncateLatLon(
          position.coords.latitude,
          position.coords.longitude,
        );
        const label = `${lat.toFixed(3)}, ${lon.toFixed(3)}`;
        writeCachedLocation({ lat, lon, label });
        void handleNearbyFromCoords(lat, lon, label).finally(() => {
          setLoadingLocation(false);
        });
      },
      (error) => {
        setLoadingLocation(false);
        setStopsError(geolocationErrorMessage(error.code));
      },
      {
        enableHighAccuracy: false,
        timeout: 12_000,
        maximumAge: 60_000,
      },
    );
  };

  const handleSearchSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (loadingLocation || loadingSearch) return;
    if (searchQuery.trim().length < 2) return;

    setLoadingSearch(true);
    setStopsError(null);
    setStops([]);
    setSelectedStop(null);
    setArrivalsResult(null);
    setLocationLabel(null);

    try {
      const data = await searchBusStops(searchQuery);
      if (data.ok === false) {
        setStopsError(data.error);
        return;
      }

      setStops(data.stops);
      await loadArrivals(data.stops[0]!);
    } catch {
      setStopsError("Failed to search stops. Try again.");
    } finally {
      setLoadingSearch(false);
    }
  };

  const handleSearchQueryChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchQuery(e.target.value);
  };

  const handleStopSelect = (stop: NearbyBusStop) => {
    void loadArrivals(stop);
  };

  const handleStopKeyDown = (e: React.KeyboardEvent<HTMLButtonElement>, stop: NearbyBusStop) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      handleStopSelect(stop);
    }
  };

  const findingStops = loadingLocation || loadingSearch;

  return (
    <div>
      <h2 className="text-xl font-semibold mb-1 flex items-center gap-2">
        <Bus className="size-5" aria-hidden />
        Bus arrivals near you
      </h2>
      <p className="text-sm text-muted-foreground mb-4 text-pretty">
        Defaults to Trafalgar Square (cached in this browser). Use my location to overwrite, or
        search by stop name. Powered by{" "}
        <code className="bg-background/60 px-1 py-0.5 text-xs">stopPoint.getByGeoPoint</code>,{" "}
        <code className="bg-background/60 px-1 py-0.5 text-xs">stopPoint.search</code>, and{" "}
        <code className="bg-background/60 px-1 py-0.5 text-xs">stopPoint.getArrivals</code>.
      </p>

      <div className="flex flex-col sm:flex-row gap-2 mb-4">
        <Button
          type="button"
          onClick={handleUseLocation}
          disabled={findingStops}
          className="sm:w-auto"
          aria-busy={loadingLocation}
        >
          {loadingLocation ? (
            <>
              <Loader2 className="size-4 animate-spin" aria-hidden />
              Finding nearby stops…
            </>
          ) : (
            <>
              <LocateFixed className="size-4" aria-hidden />
              Use my location
            </>
          )}
        </Button>

        <form onSubmit={handleSearchSubmit} className="flex flex-1 gap-2">
          <div className="flex-1">
            <Label htmlFor="tfl-bus-search" className="sr-only">
              Search bus stops
            </Label>
            <Input
              id="tfl-bus-search"
              type="search"
              value={searchQuery}
              onChange={handleSearchQueryChange}
              placeholder="Or search by street or stop name"
              className="w-full bg-background"
              aria-label="Search bus stops"
              disabled={findingStops}
            />
          </div>
          <Button
            type="submit"
            variant="outline"
            disabled={findingStops || searchQuery.trim().length < 2}
            aria-busy={loadingSearch}
          >
            {loadingSearch ? (
              <>
                <Loader2 className="size-4 animate-spin" aria-hidden />
                <span className="sr-only sm:not-sr-only">Searching…</span>
              </>
            ) : (
              <>
                <Search className="size-4 sm:mr-0" aria-hidden />
                <span className="sr-only sm:not-sr-only">Search</span>
              </>
            )}
          </Button>
        </form>
      </div>

      {stopsError && (
        <p className="text-destructive text-sm mb-4" role="alert">
          {stopsError}
        </p>
      )}

      {locationLabel && stops.length > 0 && (
        <p className="text-xs text-muted-foreground mb-3 flex items-center gap-1">
          <MapPin className="size-3.5 shrink-0" aria-hidden />
          Stops within 400m of {locationLabel} (GPS rounded to ~100m to avoid constant refreshes)
        </p>
      )}

      {stops.length > 0 && (
        <div className="mb-4">
          <p className="text-sm font-medium mb-2">Select a stop</p>
          <ul className="grid grid-cols-1 sm:grid-cols-2 gap-2 list-none p-0" role="list">
            {stops.map((stop) => {
              const isSelected = selectedStop?.id === stop.id;
              const meta = [
                stop.towards ? `towards ${stop.towards}` : null,
                stop.distance !== undefined ? `${formatDistance(stop.distance)} away` : null,
              ].filter(Boolean);

              return (
                <li key={stop.id}>
                  <button
                    type="button"
                    onClick={() => handleStopSelect(stop)}
                    onKeyDown={(e) => handleStopKeyDown(e, stop)}
                    aria-pressed={isSelected}
                    aria-label={`Show arrivals for ${stop.name}${stop.stopLetter ? ` stop ${stop.stopLetter}` : ""}${stop.towards ? `, towards ${stop.towards}` : ""}`}
                    disabled={loadingArrivals}
                    className={cn(
                      "w-full text-left p-3 border border-border transition-colors",
                      "bg-background/60 dark:bg-background/20 hover:bg-background/80",
                      isSelected && "ring-1 ring-primary border-primary",
                    )}
                  >
                    <span className="flex items-center gap-1.5 text-sm font-medium">
                      <span className="truncate">{stop.name}</span>
                      <StopLetterBadge letter={stop.stopLetter} />
                    </span>
                    {meta.length > 0 && (
                      <span className="mt-1 block text-xs text-muted-foreground text-pretty">
                        {meta.join(" · ")}
                      </span>
                    )}
                    {stop.lines && stop.lines.length > 0 && (
                      <span className="mt-1.5 flex flex-wrap gap-1">
                        {stop.lines.slice(0, 6).map((line) => (
                          <LineBadge key={line} line={line} />
                        ))}
                      </span>
                    )}
                  </button>
                </li>
              );
            })}
          </ul>
        </div>
      )}

      {(loadingArrivals || arrivalsResult !== null) && selectedStop && (
        <div className="border-t border-border pt-4">
          <h3 className="mb-3 text-sm font-semibold">
            <span className="inline-flex items-center gap-1.5">
              Arrivals: {selectedStop.name}
              <StopLetterBadge letter={selectedStop.stopLetter} />
              {loadingArrivals && (
                <Loader2 className="size-3.5 animate-spin shrink-0" aria-hidden />
              )}
            </span>
            {selectedStop.towards && (
              <span className="mt-0.5 block text-xs font-normal text-muted-foreground">
                towards {selectedStop.towards}
              </span>
            )}
          </h3>

          {arrivalsResult?.ok === false && (
            <p className="text-destructive text-sm" role="alert">
              {arrivalsResult.error}
            </p>
          )}

          {arrivalsResult?.ok === true && (
            <>
              {arrivalsResult.arrivals.length === 0 ? (
                <p className="text-muted-foreground text-sm">No buses due at this stop right now.</p>
              ) : (
                <ul className="space-y-0 list-none p-0" role="list">
                  {arrivalsResult.arrivals.slice(0, 12).map((a: BusArrival, i: number) => {
                    const clock = formatClockTime(a.expectedArrival);
                    const direction = formatDirection(a.direction);
                    const detailParts = [
                      direction,
                      a.towards && a.towards !== a.destinationName
                        ? `towards ${a.towards}`
                        : null,
                      a.vehicleId ? `veh ${a.vehicleId}` : null,
                    ].filter(Boolean);

                    return (
                      <li
                        key={`${a.lineName}-${a.destinationName}-${a.timeToStation}-${i}`}
                        className="grid grid-cols-[auto_1fr_auto] items-center gap-1.5 py-2.5 border-b border-border last:border-0 text-sm"
                      >
                        <LineBadge line={a.lineName ?? "-"} />
                        <span className="flex min-w-0 items-center gap-1.5 font-medium">
                          <span className="truncate">
                            <span className="font-normal text-muted-foreground">to</span>{" "}
                            {a.destinationName ?? "-"}
                          </span>
                          {detailParts.length > 0 && (
                            <span className="min-w-0 truncate text-xs font-normal text-muted-foreground">
                              {detailParts.join(" · ")}
                            </span>
                          )}
                        </span>
                        <span className="text-right">
                          <span className="block tabular-nums font-semibold">
                            {formatTimeToStation(a.timeToStation)}
                          </span>
                          {clock && (
                            <span className="block text-xs text-muted-foreground tabular-nums">
                              {clock}
                            </span>
                          )}
                        </span>
                      </li>
                    );
                  })}
                </ul>
              )}
            </>
          )}
        </div>
      )}
    </div>
  );
};

"use server";

import { getTflClient } from "@/lib/tfl/client";
import { isValidLatLon, truncateLatLon } from "@/lib/tfl/geo";

export type BusArrival = {
  lineName?: string;
  destinationName?: string;
  towards?: string;
  direction?: string;
  bearing?: string;
  platformName?: string;
  timeToStation?: number;
  expectedArrival?: string;
  vehicleId?: string;
};

export type NearbyBusStop = {
  id: string;
  name: string;
  indicator?: string;
  stopLetter?: string;
  towards?: string;
  distance?: number;
  lines?: string[];
};

export type GetBusArrivalsResult =
  | { ok: true; arrivals: BusArrival[]; stopName?: string }
  | { ok: false; error: string };

export type GetNearbyBusStopsResult =
  | { ok: true; stops: NearbyBusStop[]; lat: number; lon: number; radius: number }
  | { ok: false; error: string };

export type SearchBusStopsResult =
  | { ok: true; stops: NearbyBusStop[] }
  | { ok: false; error: string };

const NEARBY_RADIUS_METERS = 400;
const MAX_NEARBY_STOPS = 8;
const MAX_SEARCH_STOPS = 6;

type AdditionalProperty = { key?: string; value?: string };

const readTowards = (properties?: AdditionalProperty[]): string | undefined => {
  const value = properties?.find((prop) => prop.key?.toLowerCase() === "towards")?.value;
  return value?.trim() || undefined;
};

const readStopLetter = (stopLetter?: string, indicator?: string): string | undefined => {
  const fromLetter = stopLetter?.trim();
  if (fromLetter) return fromLetter.slice(0, 2).toUpperCase();
  const fromIndicator = indicator?.replace(/^stop\s+/i, "").trim();
  if (fromIndicator && fromIndicator.length <= 2) return fromIndicator.toUpperCase();
  return undefined;
};

const mapStopPoint = (stop: {
  id?: string;
  commonName?: string;
  name?: string;
  indicator?: string;
  stopLetter?: string;
  distance?: number;
  lines?: Array<{ name?: string }>;
  additionalProperties?: AdditionalProperty[];
}): NearbyBusStop | null => {
  if (!stop.id) return null;

  return {
    id: stop.id,
    name: (stop.commonName ?? stop.name)?.trim() || "Unknown stop",
    indicator: stop.indicator,
    stopLetter: readStopLetter(stop.stopLetter, stop.indicator),
    towards: readTowards(stop.additionalProperties),
    distance: stop.distance,
    lines: stop.lines?.map((line) => line.name).filter(Boolean) as string[] | undefined,
  };
};

const isBusStop = (modes?: string[]) => modes?.includes("bus") ?? false;

/** London bus stop points that support live arrivals (not hubs / station parents). */
const isBoardableBusStopId = (id: string) => /^490\d/i.test(id);

const mapStopsFromGeoResponse = (
  stopPoints: Array<{
    id?: string;
    commonName?: string;
    indicator?: string;
    stopLetter?: string;
    distance?: number;
    modes?: string[];
    lines?: Array<{ name?: string }>;
    additionalProperties?: AdditionalProperty[];
  }>,
  limit: number,
): NearbyBusStop[] =>
  stopPoints
    .filter((stop) => stop.id && isBusStop(stop.modes) && isBoardableBusStopId(stop.id))
    .sort((a, b) => (a.distance ?? Infinity) - (b.distance ?? Infinity))
    .slice(0, limit)
    .map(mapStopPoint)
    .filter((stop): stop is NearbyBusStop => stop !== null);

const fetchBusStopsNear = async (
  lat: number,
  lon: number,
  limit: number,
): Promise<NearbyBusStop[]> => {
  const client = getTflClient();
  const response = await client.stopPoint.getByGeoPoint({
    lat,
    lon,
    radius: NEARBY_RADIUS_METERS,
    modes: ["bus"],
    returnLines: true,
  });
  return mapStopsFromGeoResponse(response.stopPoints ?? [], limit);
};

/** Enrich search hits with stop letter / towards from full stop details. */
const enrichStops = async (stops: NearbyBusStop[]): Promise<NearbyBusStop[]> => {
  if (stops.length === 0) return stops;

  try {
    const client = getTflClient();
    const details = await client.stopPoint.get(stops.map((stop) => stop.id));
    const detailList = Array.isArray(details) ? details : [details];
    const byId = new Map(
      detailList
        .map((detail) => mapStopPoint(detail))
        .filter((stop): stop is NearbyBusStop => stop !== null)
        .map((stop) => [stop.id, stop] as const),
    );

    return stops.map((stop) => {
      const detail = byId.get(stop.id);
      if (!detail) return stop;
      return {
        ...stop,
        stopLetter: stop.stopLetter ?? detail.stopLetter,
        towards: stop.towards ?? detail.towards,
        lines: stop.lines?.length ? stop.lines : detail.lines,
        name: stop.name || detail.name,
      };
    });
  } catch {
    return stops;
  }
};

export async function getNearbyBusStops(
  lat: number,
  lon: number,
): Promise<GetNearbyBusStopsResult> {
  if (!isValidLatLon(lat, lon)) {
    return { ok: false, error: "Invalid coordinates." };
  }

  const { lat: truncatedLat, lon: truncatedLon } = truncateLatLon(lat, lon);

  try {
    const stops = await fetchBusStopsNear(truncatedLat, truncatedLon, MAX_NEARBY_STOPS);

    if (stops.length === 0) {
      return {
        ok: false,
        error: `No bus stops found within ${NEARBY_RADIUS_METERS}m. Try searching by street name instead.`,
      };
    }

    return {
      ok: true,
      stops,
      lat: truncatedLat,
      lon: truncatedLon,
      radius: NEARBY_RADIUS_METERS,
    };
  } catch (err) {
    const message = err instanceof Error ? err.message : "Failed to find nearby stops.";
    return { ok: false, error: message };
  }
}

export async function searchBusStops(query: string): Promise<SearchBusStopsResult> {
  const trimmed = query.trim();
  if (trimmed.length < 2) {
    return { ok: false, error: "Enter at least 2 characters to search." };
  }

  try {
    const client = getTflClient();
    const response = await client.stopPoint.search({
      query: trimmed,
      modes: ["bus"],
      maxResults: MAX_SEARCH_STOPS,
    });

    const matches = (response.matches ?? []).filter(
      (match) => match.id && isBusStop(match.modes),
    );

    // Prefer real boarding points (490…). Hubs like HUBLBG have no bus arrivals.
    const boardable = matches
      .filter((match) => match.id && isBoardableBusStopId(match.id))
      .map((match) =>
        mapStopPoint({
          id: match.id,
          commonName: match.name ?? match.stationName,
          indicator: match.platformName,
          lines: match.lines,
        }),
      )
      .filter((stop): stop is NearbyBusStop => stop !== null);

    if (boardable.length > 0) {
      const enriched = await enrichStops(boardable.slice(0, MAX_SEARCH_STOPS));
      return { ok: true, stops: enriched };
    }

    // Expand the first hub/station hit to nearby bus stops via its coordinates.
    const expandable = matches.find(
      (match) =>
        typeof match.lat === "number" &&
        typeof match.lon === "number" &&
        isValidLatLon(match.lat, match.lon),
    );

    if (expandable?.lat != null && expandable.lon != null) {
      const nearby = await fetchBusStopsNear(expandable.lat, expandable.lon, MAX_SEARCH_STOPS);
      if (nearby.length > 0) {
        return { ok: true, stops: nearby };
      }
    }

    return { ok: false, error: "No bus stops matched that search." };
  } catch (err) {
    const message = err instanceof Error ? err.message : "Failed to search stops.";
    return { ok: false, error: message };
  }
}

export async function getBusArrivals(
  stopId: string,
  stopName?: string,
): Promise<GetBusArrivalsResult> {
  const trimmed = stopId.trim();
  if (!trimmed) {
    return { ok: false, error: "No stop selected." };
  }

  try {
    const client = getTflClient();
    const arrivals = await client.stopPoint.getArrivals({
      stopPointIds: [trimmed],
      sortBy: "timeToStation",
    });
    const mapped: BusArrival[] = arrivals.map((arrival) => ({
      lineName: arrival.lineName,
      destinationName: arrival.destinationName,
      towards: arrival.towards,
      direction: arrival.direction,
      bearing: arrival.bearing,
      platformName: arrival.platformName,
      timeToStation: arrival.timeToStation,
      expectedArrival: arrival.expectedArrival,
      vehicleId: arrival.vehicleId,
    }));
    return { ok: true, arrivals: mapped, stopName };
  } catch (err) {
    const message = err instanceof Error ? err.message : "Failed to fetch arrivals.";
    if (message.includes("404")) {
      return {
        ok: false,
        error: "This stop has no live bus arrivals. Pick a stop with a letter (e.g. Stop R).",
      };
    }
    return { ok: false, error: message };
  }
}

/** ~111 m grid; stable enough to avoid mobile GPS jitter re-fetching. */
export const COORD_PRECISION = 3;

/** Demo / fallback pin — Nelson’s Column, Trafalgar Square. */
export const TRAFALGAR_SQUARE = {
  lat: 51.508,
  lon: -0.128,
  label: "Trafalgar Square",
} as const;

export type LatLonLabel = {
  lat: number;
  lon: number;
  label: string;
};

export const truncateCoord = (value: number, precision = COORD_PRECISION): number => {
  const factor = 10 ** precision;
  return Math.round(value * factor) / factor;
};

export const truncateLatLon = (
  lat: number,
  lon: number,
  precision = COORD_PRECISION,
): { lat: number; lon: number } => ({
  lat: truncateCoord(lat, precision),
  lon: truncateCoord(lon, precision),
});

export const isValidLatLon = (lat: number, lon: number): boolean =>
  Number.isFinite(lat) &&
  Number.isFinite(lon) &&
  lat >= -90 &&
  lat <= 90 &&
  lon >= -180 &&
  lon <= 180;

import TflClient from "tfl-ts";

export const getTflClient = (): TflClient => {
  const appId = process.env.TFL_APP_ID;
  const appKey = process.env.TFL_APP_KEY;
  if (appId && appKey) {
    return new TflClient({ appId, appKey });
  }
  return new TflClient();
};
